import requests
from pathlib import Path
import zipfile

DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    if not url or not filename:
        return ("Error: Invalid input parameters", [])

    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)

    try:
        response = requests.get(url, stream=True, timeout=10)
        response.raise_for_status()
    except Exception as e:
        return (f"Error: Network issue - {str(e)}", [])

    zip_path = DOWNLOAD_DIR / filename
    try:
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except Exception as e:
        return (f"Error: File write issue - {str(e)}", [])

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
    except Exception as e:
        return (f"Error: Extraction issue - {str(e)}", [])

    try:
        extracted_files = [f.name for f in ZIP_DIR.iterdir() if f.is_file()]
    except Exception as e:
        return (f"Error: Listing files issue - {str(e)}", [])

    return ("Success", extracted_files)
